topics.styles:
.lesson .basic-selectors p {
    color: blue;
}
.lesson .basic-selectors .highlight {
    background-color: yellow;
    font-weight: bold;
}
.lesson .basic-selectors #unique-title {
    color: red;
    text-decoration: underline;
}


.lesson .group-selectors h2,
.lesson .group-selectors h3,
.lesson .group-selectors p {
    color: green;
    font-family: Arial, sans-serif;
}


.lesson .combinator-selectors div p {
    color: blue;
}
.lesson .combinator-selectors div > p {
    font-weight: bold;
}
.lesson .combinator-selectors h4 + p {
    color: red;
}
.lesson .combinator-selectors h4 ~ p {
    font-style: italic;
}


.lesson .attribute-selectors [title] {
    color: purple;
}
.lesson .attribute-selectors [type="text"] {
    border: 2px solid blue;
}
.lesson .attribute-selectors [href^="https"] {
    color: green;
}
.lesson .attribute-selectors [href$=".pdf"] {
    color: red;
}
.lesson .attribute-selectors [class*="btn"] {
    background-color: orange;
    color: white;
    border: none;
    padding: 5px 10px;
    border-radius: 5px;
}


.lesson .pseudo-classes a:hover {
    color: red;
    text-decoration: underline;
}
.lesson .pseudo-classes input:focus {
    border: 2px solid green;
}
.lesson .pseudo-classes li:first-child {
    font-weight: bold;
}
.lesson .pseudo-classes li:last-child {
    color: blue;
}


.lesson .pseudo-elements p::first-letter {
    font-size: 24px;
    color: red;
}
.lesson .pseudo-elements p::first-line {
    font-weight: bold;
}
.lesson .pseudo-elements p::selection {
    background: yellow;
    color: black;
}

.lesson .specificity-demo p {
    color: blue;
}
.lesson .specificity-demo .highlight {
    color: green;
}
.lesson .specificity-demo #special {
    color: red;
}
.lesson .specificity-demo p#special {
    color: orange;
}


.lesson .important-demo p {
    color: blue !important;
}
.lesson .important-demo #special {
    color: red;
}


.lesson .inheritance-demo .parent {
    color: green;
    font-family: Arial, sans-serif;
}
.lesson .inheritance-demo p {
    font-size: 18px;
}

/* Box Model Demo */
.lesson .boxmodel-demo {
    margin: 30px;
    background-color: orange; /* Margin area visualization */
    padding: 20px;
}

.lesson .box-content {
    padding: 20px;
    border: 5px solid #201c39ff;
    background-color: #00085dff;
    text-align: center;
    font-weight: bold;
    color: #fbfbffff;
    transition: 0.3s ease;
}

.lesson .box-content:hover {
    background-color: #77aad2ff;
    border-color: #003f80;
}

/* Box Sizing Example */
.lesson .box-sizing-example {
    display: flex;
    gap: 20px;
    margin-top: 20px;
}

.lesson .content-box,
.lesson .border-box {
    padding: 20px;
    border: 5px solid;
    text-align: center;
    background-color: #040145ff;
}

.lesson .content-box {
    box-sizing: content-box;
    border-color: blue;
}

.lesson .border-box {
    box-sizing: border-box;
    border-color: green;
}

/* Generic card and demo styling */
.lesson .demo-box {
    padding: 15px;
    margin: 10px 0;
    text-align: center;
    border-radius: 8px;
    color: white;
    font-weight: bold;
}

/* COLORS */
.lesson .text-colors-demo p {
    font-size: 16px;
    margin: 8px 0;
    color: red; /* Default color */
}
.lesson .text-colors-demo .hex { color: #3498db; }
.lesson .text-colors-demo .rgb { color: rgb(34, 193, 195); }
.lesson .text-colors-demo .rgba { color: rgba(255, 0, 0, 0.6); }
.lesson .text-colors-demo .hsl { color: hsl(120, 100%, 30%); }

/* BACKGROUNDS */
.lesson .bg-solid {
    background-color: lightblue;
    color: #000;
}
.lesson .bg-image {
    background-image: url('https://via.placeholder.com/300x150');
    background-size: cover;
    background-position: center;
}
.lesson .bg-gradient {
    background: linear-gradient(to right, #ff7e5f, #feb47b);
}

.lesson .background-demo {
    display: flex;
    gap: 15px;
    flex-wrap: wrap;
}
.lesson .background-demo .demo-box {
    flex: 1 1 30%;
    min-width: 150px;
}

/* TYPOGRAPHY */
.lesson .font-family-demo {
    font-family: 'Roboto', Arial, sans-serif;
}
.lesson .font-size-demo {
    font-size: 24px;
}
.lesson .font-weight-demo {
    font-weight: bold;
}
.lesson .italic-demo {
    font-style: italic;
}
.lesson .uppercase-demo {
    text-transform: uppercase;
}
.lesson .spacing-demo {
    letter-spacing: 2px;
    word-spacing: 10px;
}

/* Ensure demo styles only affect demo areas */
.lesson .typography-demo p {
    padding: 5px 0;
}

