.lesson .demo-label { color:#94a3b8; font-size:13px; margin:12px 0 0; }

.lesson .demo-flex { display:flex; gap:10px; }
.lesson .demo-between { justify-content:space-between; }
.lesson .demo-center { justify-content:center; align-items:center; height:110px; }
