.lesson .pseudo-class-demo a:hover {
    color: red;
    text-decoration: underline;
}
.lesson .pseudo-class-demo input:focus {
    border: 2px solid green;
}
.lesson .pseudo-class-demo li:first-child {
    font-weight: bold;
}
.lesson .pseudo-class-demo li:last-child {
    color: blue;
}
.lesson .pseudo-class-demo li:nth-child(2) {
    background-color: #696923;
}


.lesson .pseudo-element-demo p::first-letter {
    font-size: 24px;
    color: red;
}
.lesson .pseudo-element-demo p::first-line {
    font-weight: bold;
}
.lesson .pseudo-element-demo p::selection {
    background: yellow;
    color: black;
}
.lesson .pseudo-element-demo .box::before {
    content: "Start - ";
    color: green;
}
.lesson .pseudo-element-demo .box::after {
    content: " - End";
    color: blue;
}


.lesson .pseudo-combined-demo .button {
    position: relative;
    padding: 10px 20px;
    background: #07284dff;
    color: white;
    border: none;
    cursor: pointer;
    font-size: 16px;
    border-radius: 5px;
    transition: background 0.3s ease;
}
.lesson .pseudo-combined-demo .button:hover {
    background: #162d46ff;
}
.lesson .pseudo-combined-demo .button::after {
    content: " →";
    position: absolute;
    right: 10px;
}

